	@ParameterizedTest
	@ValueSource(booleans = { true, false })
	void typedStatementsContextsAndDatasetsKeepForeignAlternativesSeparate(boolean nativeStore) throws IOException {
		try (var fixture = fixture(nativeStore); var connection = fixture.federation.getConnection()) {
			var vf = SimpleValueFactory.getInstance();
			var row = rows(fixture.federation,
					"SELECT ?s ?g WHERE { ?s <urn:p> ?p . GRAPH ?g { ?s <urn:graph-q> ?q } }").get(0);
			var subject = (Resource) row.getValue("s");
			var graph = (Resource) row.getValue("g");
			var graphs = new ArrayList<Resource>();
			try (var contexts = connection.getContextIDs()) {
				while (contexts.hasNext()) {
					graphs.add(contexts.next());
				}
			}
			assertEquals(4, graphs.size());
			assertTrue(connection.hasStatement(subject, vf.createIRI("urn:graph-q"), null, false, graph));
			try (var statements = connection.getStatements(subject, vf.createIRI("urn:graph-q"), null, false,
					graphs.toArray(Resource[]::new))) {
				assertTrue(statements.hasNext());
				assertEquals(subject, statements.next().getSubject());
				assertFalse(statements.hasNext());
			}
			var nonmatching = new ArrayList<Resource>();
			for (Resource candidate : graphs) {
				if (!connection.hasStatement(subject, vf.createIRI("urn:graph-q"), null, false, candidate)) {
					nonmatching.add(candidate);
				}
			}
			assertEquals(3, nonmatching.size());
			try (var statements = connection.getStatements(subject, vf.createIRI("urn:graph-q"), null, false,
					nonmatching.toArray(Resource[]::new))) {
				assertFalse(statements.hasNext());
			}
			for (List<Resource> selection : List.of(graphs, nonmatching)) {
				SimpleDataset dataset = new SimpleDataset();
				selection.forEach(dataset::addNamedGraph);
				var query = connection.prepareTupleQuery("SELECT ?q WHERE { GRAPH ?g { ?s <urn:graph-q> ?q } }");
				query.setBinding("s", subject);
				query.setDataset(dataset);
				try (var result = query.evaluate()) {
					assertEquals(selection == graphs, result.hasNext());
					if (result.hasNext()) {
						assertEquals("q", result.next().getValue("q").stringValue());
						assertFalse(result.hasNext());
					}
				}
			}
		}
	}

