	private Fixture fixture(boolean nativeStore) throws IOException {
		AtomicInteger prepared = new AtomicInteger();
		Endpoint first = nativeStore
				? EndpointFactory.loadNativeEndpoint("first",
						Files.createDirectory(temporary.resolve("first")).toFile())
				: EndpointFactory.loadEndpoint("first", countingRepository(prepared));
		Endpoint second = nativeStore
				? EndpointFactory.loadNativeEndpoint("second",
						Files.createDirectory(temporary.resolve("second")).toFile())
				: EndpointFactory.loadEndpoint("second", countingRepository(prepared));
		var federation = FedXFactory.newFederation()
				.withMembers(List.of(first, second))
				.withConfig(new FedXConfig().withEnableTripleRefSupport(true))
				.create();
		federation.init();
		for (var endpoint : List.of(first, second)) {
			try (var connection = endpoint.getConnection()) {
				var vf = connection.getValueFactory();
				for (int index = 0; index < 2; index++) {
					var node = vf.createBNode("same-" + index);
					var object = vf.createBNode("object-" + index);
					var graph = vf.createBNode("graph-" + index);
					var term = vf.createTripleTerm(node, vf.createIRI("urn:inner"),
							vf.createTripleTerm(object, vf.createIRI("urn:inner"), vf.createLiteral(index)));
					if (endpoint == first) {
						connection.add(node, vf.createIRI("urn:p"), vf.createLiteral("p"));
						connection.add(node, vf.createIRI("urn:link"), object);
						connection.add(node, vf.createIRI("urn:term"), term);
					}
					connection.add(node, vf.createIRI("urn:q"), vf.createLiteral("q"));
					connection.add(node, vf.createIRI("urn:graph-q"), vf.createLiteral("q"), graph);
					connection.add(object, vf.createIRI("urn:value"), vf.createLiteral("v"));
					connection.add(vf.createIRI("urn:holder-" + index), vf.createIRI("urn:lookup"), term);
					var reifier = vf.createBNode("reifier-" + index);
					connection.add(reifier, RDF.REIFIES,
							vf.createTripleTerm(node, vf.createIRI("urn:quoted"), vf.createLiteral(index)));
					connection.add(reifier, vf.createIRI("urn:annotation"), vf.createLiteral("annotation"));
					if (endpoint == second) {
						connection.add(node, vf.createIRI("urn:foreign"), vf.createLiteral("foreign"));
					}
				}
				if (endpoint == second) {
					connection.add(vf.createIRI("urn:only-b"), vf.createIRI("urn:label"), vf.createLiteral("b"));
				}
			}
		}
		return new Fixture(federation, second, prepared);
	}

	private static Repository countingRepository(AtomicInteger prepared) {
		return new RepositoryWrapper(new SailRepository(new MemoryStore())) {
			@Override
			public RepositoryConnection getConnection() {
				return new RepositoryConnectionWrapper(this, super.getConnection()) {
					@Override
					public TupleQuery prepareTupleQuery(QueryLanguage language, String query, String baseURI) {
						prepared.incrementAndGet();
						return super.prepareTupleQuery(language, query, baseURI);
					}
				};
			}
		};
	}

	private static List<BindingSet> rows(FedXRepository federation, String sparql) {
		try (var connection = federation.getConnection();
				var result = connection.prepareTupleQuery(sparql).evaluate()) {
			var rows = new ArrayList<BindingSet>();
			while (result.hasNext()) {
				rows.add(result.next());
			}
			return rows;
		}
	}

	private record Fixture(FedXRepository federation, Endpoint second, AtomicInteger prepared)
			implements AutoCloseable {
		@Override
		public void close() {
			federation.shutDown();
		}
	}
